    if ((rt.truthy(g.gml_script_isCollisionLeft(self, other, 1.0)) or rt.truthy(g.gml_script_isCollisionRight(self, other, 1.0)))) {
        self.vars[g.VAR_xVel] = (-self.vars[g.VAR_xVel]);
    }
    if (rt.truthy(g.gml_script_isCollisionSolid(self, other))) {
        api.iset_y(self, (api.iget_y(self) - 2.0));
    }
}
